{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 금연구역 지정 공원에서 담배를 입에 대지 않고 불을 붙여 들고만 있어도 과태료 부과 대상인지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "네, 과태료 부과 대상입니다. 이 조례에서 \"흡연\"은 담배를 피우는 행위뿐 아니라 불이 붙은 담배를 소지하는 것도 포함하므로, 입에 대지 않았더라도 불이 붙은 담배를 들고 있는 행위는 흡연에 해당합니다. 금연구역으로 지정된 도시공원에서는 누구든지 흡연을 해서는 안 되며, 이를 위반하면 시장이 10만원의 과태료를 부과·징수합니다.",
          "b_ids": "금연:제2조제2호, 금연:제5조제1항제1호, 금연:제5조제4항, 금연:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
